sys_script_include.script:
var FleetBlackoutUtils = Class.create();

/**
 * FLEET-18: true if any blackout overlaps the range (start < blackout.end AND end > blackout.start)
 * and applies to the depot (affected_depots empty = all depots).
 * Touching boundaries do not overlap.
 * @param {GlideDateTime|string} startGdt - range start (UTC internal value when a string)
 * @param {GlideDateTime|string} endGdt - range end
 * @param {string} [depotSysId] - cmn_location sys_id; empty = any depot
 * @returns {boolean}
 */
FleetBlackoutUtils.overlaps = function(startGdt, endGdt, depotSysId) {
    if (!startGdt || !endGdt) {
        return false;
    }
    var start = new GlideDateTime(startGdt);
    var end = new GlideDateTime(endGdt);

    var blk = new GlideRecord('x_1850693_enterp_0_blackout');
    blk.addQuery('start_datetime', '<', end.getValue());
    blk.addQuery('end_datetime', '>', start.getValue());
    if (depotSysId) {
        blk.addEncodedQuery('affected_depotsISEMPTY^ORaffected_depotsLIKE' + depotSysId);
    }
    blk.setLimit(1);
    blk.query();
    return blk.hasNext();
};

FleetBlackoutUtils.prototype = {
    initialize: function() {},
    type: 'FleetBlackoutUtils'
};
